<?php $pageTitle='Tournament';require_once dirname(__DIR__).'/includes/header.php';require_once dirname(__DIR__).'/includes/auth.php';require_auth(['super_admin','admin']);
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf($_POST['csrf_token']??null);$name=trim($_POST['name']??'');if($name===''||!strtotime($_POST['start_date']??'')||!strtotime($_POST['end_date']??''))throw new RuntimeException('Complete all required fields.');$stmt=$pdo->prepare('INSERT INTO tournaments (name,description,start_date,end_date,location,type,maximum_participants,status) VALUES (?,?,?,?,?,?,?,?)');$stmt->execute([$name,trim($_POST['description']??''),$_POST['start_date'],$_POST['end_date'],trim($_POST['location']),$_POST['type'],max(2,(int)$_POST['maximum_participants']),$_POST['status']]);audit_log($pdo,'create','tournament',(int)$pdo->lastInsertId(),'Created tournament '.$name);header('Location: tournaments.php?created=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}
require dirname(__DIR__).'/includes/sidebar.php';$rows=$pdo->query('SELECT t.*,(SELECT COUNT(*) FROM participants p WHERE p.tournament_id=t.id) participant_count FROM tournaments t ORDER BY created_at DESC')->fetchAll();?>
<div class="grid grid-2"><section class="card"><div class="section-head"><div><div class="eyebrow">Configuration</div><h2>Create tournament</h2></div></div><?php if(!empty($error)):?><p style="color:#fca5a5"><?=e($error)?></p><?php endif;?><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-group full"><label>Tournament Name</label><input name="name" required></div><div class="form-group full"><label>Description</label><textarea name="description" rows="3"></textarea></div><div><label>Start Date</label><input type="date" name="start_date" required></div><div><label>End Date</label><input type="date" name="end_date" required></div><div class="form-group full"><label>Location</label><input name="location" required></div><div><label>Tournament Type</label><select name="type"><option value="single_elimination">Single Elimination</option><option value="double_elimination" disabled>Double Elimination (future)</option><option value="round_robin" disabled>Round Robin (future)</option></select></div><div><label>Maximum Participants</label><input type="number" name="maximum_participants" min="2" max="256" value="16"></div><div><label>Status</label><select name="status"><option value="upcoming">Upcoming</option><option value="live">Live</option><option value="finished">Finished</option></select></div><div class="form-group full"><button class="btn btn-primary" type="submit">Create Tournament</button></div></form></section><section><div class="section-head"><div><div class="eyebrow">All events</div><h2>Tournaments</h2></div></div><div class="grid"><?php foreach($rows as $r):?><div class="card"><div class="match-card-head"><strong><?=e($r['name'])?></strong><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></div><p style="color:var(--text-secondary)"><i class="fa-solid fa-location-dot"></i> <?=e($r['location'])?></p><div class="match-card-foot"><span><?=$r['participant_count']?> participants</span><span><?=date('d M Y',strtotime($r['start_date']))?></span></div></div><?php endforeach;?></div></section></div>
